-- 2026-11-11 1.2.2 去掉条目内残留的“四、/五、”章节前缀
begin;
create temp table _kbic2(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kbic2 values (46, $kbic2$[{"t":"list","id":"a1-1-2-2-b1","imp":"core","items":["1、==微电子技术基础元件的演变==：电子管阶段产生了广播、电视、无线电通信、仪器仪表、自动化技术和第一代电子计算机。晶体管于1948年发明，加上印制电路组装技术的使用，使电子电路在小型化方面前进了一大步，产生了第二代计算机。集成电路（Integrated Circuit，简称IC）于20世纪50年代出现，以半导体单晶片作为材料；现代集成电路使用的半导体材料通常是硅（Si），也可以是砷化镓（GaAs）等化合物半导体。小规模集成电路使电子电路进一步缩小，产生了第三代计算机；超大规模集成电路使电子电路微型化，产生了第四代计算机。目前所使用的计算机都属于第四代计算机。","2、==集成电路按所含电子元件数目分类==：^^按所包含的电子元件数目分^^：","1）中小规模集成电路，集成对象为门电路或单级放大器；","2）大规模集成电路，集成对象为功能部件、子系统；","3）PC机使用的微处理器、芯片组、图形加速芯片都是超大规模（VLSI）和极大规模集成电路。","3、==集成电路按用途分类==：按用途分为==通用集成电路和专用集成电路（ASIC==，Application Specific Integrated Circuit）。专用集成电路是指应特定用户要求和特定电子系统的需要而设计、制造的集成电路。目前用CPLD（复杂可编程逻辑器件）和FPGA（现场可编程逻辑阵列）进行ASIC设计是最为流行的方式之一，它们的共性是都具有用户现场可编程特性，都支持边界扫描技术，但两者在集成度、速度以及编程方式上各有特点。","4、^^集成电路按功能分类^^：按功能分为^^数字集成电路和模拟集成电路^^。数字集成电路如逻辑电路、存储器、微处理器、微控制器、数字信号处理器等；模拟集成电路又称为线性电路，如信号放大器、功率放大器等。","5、==按晶体管结构、电路和工艺分类==：双极型电路、金属氧化物半导体（MOS）电路、双极-金属化物半导体集成电路等","6、^^集成电路的发展趋势^^：集成度的提高规律（Moore定律）：单块集成电路的集成度平均每18～24个月翻一番（目前符合）。集成电路的出路：量子计算机、光子计算机、生物（酶）计算机。","7、==IC 卡，即集成电路卡，它是把集成电路芯片密封在塑料卡基片内，使其成为能存储信息、处理和传递数据的载体。==","8、^^IC 卡特点：存储信息量大、保密性能强、可以防止伪造和窃用、抗干扰能力强、可靠性高^^","9、==IC 卡的类型（按芯片分类）==：","（1）==存储器卡==","①、原理：封装的集成电路以存储器为主，信息可长期保存，也可通过读卡器改写。","②、特点：有写保护和加密电路，可以对存储卡进行加密操作。","③、适用场景：^^校园卡、公交卡、医保卡、消费卡、门禁卡等^^。","（2）==CPU 卡==：","①、原理：封装的集成电路为中央处理器（CPU）、数据存储器、程序处理器，以及带有芯片操作系统。","②、特点： 处理能力强，保密性能更好","③、适用场景：^^银行卡、信用卡、证件、手机SIM 卡^^等","10、==IC 卡的类型（按使用方式分类）==","（1）==接触式IC 卡（如电话卡）==","①、工作原理：使用时必须将IC 卡插入读卡机，通过金属触点传输数据","②、特点：易磨损、怕脏、寿命短等","③、适用场景：信息量大、读写操作复杂场合","（2）==非接触式IC 卡（即射频卡、感应卡；如身份证）==","①、原理：采用电磁感应方式无线传输数据，无源（卡中无电源）和免接触","②、特点：操作方便，快捷，采用全密封胶固化，防水、防污，使用寿命长","③、适用场景：用于读写信息较简单的场合，如身份验证等","（3）==双界面卡（如公交一卡通、银行IC 卡）==","①、原理：可通过接触方式的触点，也可相隔一定距离以射频方式使用的IC 卡","②、特点：一卡多用、一卡通用、高度安全、快速交易等","③、适用场景：适用于恶劣工作环境和自助消费场所，适用于对安全性要求高的系统，可作为金融电子钱包应用。","11、==IC卡应用（所有IC卡都可以加密）==","（1）^^按芯片分^^：==CPU卡==，卡中既有硬件也有操作系统，安全级别高（信用卡、SIM卡、身份证）；存储器卡，用于安全级别不高的场合（饭卡、公交卡）。","12、==身份鉴别==：^^又名真实性鉴别、身份认证。 定义^^：证实某人或某物（消息、文件、主机等）的真实身份与其所声称的身份是否相符的过程。 目的：防止欺诈和假冒攻击。 认证方式：IC卡、磁卡、USB钥匙、口令、眼底虹膜等。 在计算机系统中，单纯采用令牌（如IC卡、磁卡等）进行身份认证的缺点是：丢失令牌将导致他人能轻易进行假冒，从而带来安全隐患。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-2-2-b2","imp":"core","kind":"tip","text":"集成电路按集成度分为：==小规模（SSI，<100 个元器件）、中规模（MSI）、大规模（LSI）、超大规模（VLSI）与甚大规模（ULSI）==；IC 卡按芯片类型分为==存储器卡（只含 EEPROM）与 CPU 卡（含微处理器与操作系统，安全性极高）==；按接口分为接触式与非接触式（RFID/NFC）。","title":"考向复习提示：集成电路规模划分与 IC 卡分类"},{"t":"callout","id":"a1-1-2-2-b3","imp":"core","kind":"trap","text":"==磁卡（通过磁条记录信息）极易被消磁与复制，安全性低==；而 ==IC 卡（内嵌半导体芯片）防磁、防潮、存储容量大且支持硬件级加密认证==；专转本常考单选：第三代居民身份证和现代银行芯片卡均属于==非接触式 CPU 卡==，切勿误选为磁卡或普通存储卡。","title":"高频易错陷阱：磁卡与 IC 卡的安全性辨析"}]$kbic2$::jsonb, $kbic2se$A1-1.2.2 集成电路发展与分类，IC 卡。 1、微电子技术基础元件的演变：电子管阶段产生了广播、电视、无线电通信、仪器仪表、自动化技术和第一代电子计算机。晶体管于1948年发明，加上印制电路组装技术的使用，使电子电路在小型化方面前进了一大步，产生了第二代计算机。集成电路（Integrated Circuit，简称IC）于20世纪50年代出现，以半导体单晶片作为材料；现代集成电路使用的半导体材料通常是硅（Si），也可以是砷化镓（GaAs）等化合物半导体。小规模集成电路使电子电路进一步缩小，产生了第三代计算机；超大规模集成电路使电子电路微型化，产生了第四代计算机。目前所使用的计算机都属于第四代计算机。 2、集成电路按所含电子元件数目分类：按所包含的电子元件数目分： 1）中小规模集成电路，集成对象为门电路或单级放大器； 2）大规模集成电路，集成对象为功能部件、子系统； 3）PC机使用的微处理器、芯片组、图形加速芯片都是超大规模（VLSI）和极大规模集成电路。 3、集成电路按用途分类：按用途分为通用集成电路和专用集成电路（ASIC，Application Specific Integrated Circuit）。专用集成电路是指应特定用户要求和特定电子系统的需要而设计、制造的集成电路。目前用CPLD（复杂可编程逻辑器件）和FPGA（现场可编程逻辑阵列）进行ASIC设计是最为流行的方式之一，它们的共性是都具有用户现场可编程特性，都支持边界扫描技术，但两者在集成度、速度以及编程方式上各有特点。 4、集成电路按功能分类：按功能分为数字集成电路和模拟集成电路。数字集成电路如逻辑电路、存储器、微处理器、微控制器、数字信号处理器等；模拟集成电路又称为线性电路，如信号放大器、功率放大器等。 5、按晶体管结构、电路和工艺分类：双极型电路、金属氧化物半导体（MOS）电路、双极-金属化物半导体集成电路等 6、集成电路的发展趋势：集成度的提高规律（Moore定律）：单块集成电路的集成度平均每18～24个月翻一番（目前符合）。集成电路的出路：量子计算机、光子计算机、生物（酶）计算机。 7、IC 卡，即集成电路卡，它是把集成电路芯片密封在塑料卡基片内，使其成为能存储信息、处理和传递数据的载体。 8、IC 卡特点：存储信息量大、保密性能强、可以防止伪造和窃用、抗干扰能力强、可靠性高 9、IC 卡的类型（按芯片分类）： （1）存储器卡 ①、原理：封装的集成电路以存储器为主，信息可长期保存，也可通过读卡器改写。 ②、特点：有写保护和加密电路，可以对存储卡进行加密操作。 ③、适用场景：校园卡、公交卡、医保卡、消费卡、门禁卡等。 （2）CPU 卡： ①、原理：封装的集成电路为中央处理器（CPU）、数据存储器、程序处理器，以及带有芯片操作系统。 ②、特点： 处理能力强，保密性能更好 ③、适用场景：银行卡、信用卡、证件、手机SIM 卡等 10、IC 卡的类型（按使用方式分类） （1）接触式IC 卡（如电话卡） ①、工作原理：使用时必须将IC 卡插入读卡机，通过金属触点传输数据 ②、特点：易磨损、怕脏、寿命短等 ③、适用场景：信息量大、读写操作复杂场合 （2）非接触式IC 卡（即射频卡、感应卡；如身份证） ①、原理：采用电磁感应方式无线传输数据，无源（卡中无电源）和免接触 ②、特点：操作方便，快捷，采用全密封胶固化，防水、防污，使用寿命长 ③、适用场景：用于读写信息较简单的场合，如身份验证等 （3）双界面卡（如公交一卡通、银行IC 卡） ①、原理：可通过接触方式的触点，也可相隔一定距离以射频方式使用的IC 卡 ②、特点：一卡多用、一卡通用、高度安全、快速交易等 ③、适用场景：适用于恶劣工作环境和自助消费场所，适用于对安全性要求高的系统，可作为金融电子钱包应用。 11、IC卡应用（所有IC卡都可以加密） （1）按芯片分：CPU卡，卡中既有硬件也有操作系统，安全级别高（信用卡、SIM卡、身份证）；存储器卡，用于安全级别不高的场合（饭卡、公交卡）。 12、身份鉴别：又名真实性鉴别、身份认证。 定义：证实某人或某物（消息、文件、主机等）的真实身份与其所声称的身份是否相符的过程。 目的：防止欺诈和假冒攻击。 认证方式：IC卡、磁卡、USB钥匙、口令、眼底虹膜等。 在计算机系统中，单纯采用令牌（如IC卡、磁卡等）进行身份认证的缺点是：丢失令牌将导致他人能轻易进行假冒，从而带来安全隐患。 考向复习提示：集成电路规模划分与 IC 卡分类 集成电路按集成度分为：小规模（SSI，<100 个元器件）、中规模（MSI）、大规模（LSI）、超大规模（VLSI）与甚大规模（ULSI）；IC 卡按芯片类型分为存储器卡（只含 EEPROM）与 CPU 卡（含微处理器与操作系统，安全性极高）；按接口分为接触式与非接触式（RFID/NFC）。 高频易错陷阱：磁卡与 IC 卡的安全性辨析 磁卡（通过磁条记录信息）极易被消磁与复制，安全性低；而 IC 卡（内嵌半导体芯片）防磁、防潮、存储容量大且支持硬件级加密认证；专转本常考单选：第三代居民身份证和现代银行芯片卡均属于非接触式 CPU 卡，切勿误选为磁卡或普通存储卡。$kbic2se$);
do $$
declare r record; old_rev record; v_rev integer;
begin
  for r in select node_id, blocks, search_text from _kbic2 loop
    select rev_no, html, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 找不到已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v_rev, r.blocks, old_rev.html, r.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
